In a `.pnpmfile.cjs` in the root of your monorepo, you will need:

```js
function readPackage(pkg) {
  if (pkg.name === "oclif" && pkg.version.startsWith("4.")) {
    pkg.dependencies = {
      ...pkg.dependencies,
      "package-manager-detector": "^1.2.0",
    };
  }

  return pkg;
}

module.exports = {
  hooks: {
    readPackage,
  },
};
```
